-- Sports: tennis court, soccer pitch, footy goals and netball court on the premium upgrade system, and
-- the basketball court moved into the same Marketplace tab. Additive catalogue plus one metadata update.
-- Each sport has an unlock row (Marketplace: Sports) and three upgrades bought from the in-world Upgrade
-- button; all are XP purchases through the existing purchase_economy_item_secure. The basketball row only
-- changes which tab it shows in; its price, keys and ownership are untouched. No functions or grants change.
-- Generated from lib/world3d/premium-homes.ts (checked by scripts/sports-test.mjs). 16 rows.
-- Rollback: delete from public.economy_items where item_key like 'central_world_plot_1_sport_%' or item_key like 'central_world_sports_upgrade_%';
--           update public.economy_items set metadata = metadata || '{"marketplaceCategory":"pools_play","worldArea":"pools_play"}'::jsonb where item_key = 'central_world_plot_1_play_basketball';
begin;
on conflict (item_key) do nothing;
update public.economy_items
set metadata = metadata || '{"marketplaceCategory":"sports","worldArea":"sports"}'::jsonb
where item_key = 'central_world_plot_1_play_basketball';
commit;
